<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Product extends Model {protected $guarded=[]; public function inventory(){return $this->hasMany(Inventory::class);} public function inventoryMovements(){return $this->hasMany(InventoryMovement::class);} public function customerSuppliedParts(){return $this->hasMany(CustomerSuppliedPart::class);} public function emergencyPurchases(){return $this->hasMany(EmergencyPurchase::class);} public function jobParts(){return $this->hasMany(JobPart::class);} public function purchaseOrderItems(){return $this->hasMany(PurchaseOrderItem::class);} public function stockTransferItems(){return $this->hasMany(StockTransferItem::class);} public function warranties(){return $this->hasMany(Warranty::class);} public function category(){return $this->belongsTo(Category::class);}}
